// #92bd0e (3a666c3dd8f5b45f7892bd0e) — пользователь удалённого бизнеса видит «החשבון העסקי נמחק», заблокированного — «החשבון העסקי אינו פעיל».
// #922c63 (5121408da9c3e79d47922c63) — удалённый из бизнеса видит «הגישה לעסק הוסרה», заблокированный — «הגישה לחשבון חסומה».
// spec: specs/auth-login.md (раздел 6) · кейсы AUTH-LG-010, AUTH-LG-012 · seed: tests/seed.spec.ts (гость).
// Экран входа берёт причину из адреса /login?notice=blocked&reason=<user|removed|business|deleted> — тот же компонент
// (data-testid=account-blocked), который показывается после выхода из сессии и после отказа на входе (бандл index-BT4tmDRk.js).
// Реальные блокировка/удаление с вступившим пользователем — ручные AUTH-LG-011, AUTH-LG-013 (нужен пароль).
// Только просмотр гостем → @prod-safe.
import { test, expect } from '@playwright/test';

const SUPPORT = 'פנייה לתמיכה';
// С #af074d (17b180ffa7055a7916af074d, עבר QA 04.11.2026): user / business / без причины — один текст кадра Figma 721:1134.
// Раскладка экрана (без формы, «צוות התמיכה», «חזרה לכניסה») — tests/auth-login/blocked-screen-af074d.spec.ts.
const BLOCKED_TITLE = 'הכניסה לחשבון חסומה';
const BLOCKED_BODY = 'החשבון שלכם או החשבון של העסק חסום כרגע, ולכן לא ניתן להיכנס. צוות התמיכה יוכל לבדוק מה קרה ולעזור לכם להמשיך.';

type Reason = 'deleted' | 'business' | 'removed' | 'user' | 'unknown';

async function openNotice(page: import('@playwright/test').Page, reason: Reason | null) {
  await page.goto(reason ? `/login?notice=blocked&reason=${reason}` : '/login?notice=blocked');
  const notice = page.getByTestId('account-blocked');
  await expect(notice).toBeVisible();
  await expect(notice).toHaveAttribute('data-reason', reason ?? 'unknown');
  await expect(notice.getByRole('link', { name: SUPPORT })).toHaveAttribute('href', /^mailto:/);
  // Это экран входа, а не кабинет.
  await expect(page.getByRole('button', { name: 'התנתקות' })).toHaveCount(0);
  return notice;
}

test.describe('Вход — сообщение по причине отказа: бизнес удалён / заблокирован (#92bd0e · #3a666c3dd8f5b45f7892bd0e)', () => {
  test('гость: reason=deleted → «החשבון העסקי נמחק… הגישה אליו לא תחזור», без «הגישה לחשבון חסומה» @desktop @prod-safe #92bd0e #3a666c3dd8f5b45f7892bd0e', async ({ page }) => {
    const notice = await openNotice(page, 'deleted');
    // «מה רצוי» #92bd0e: для удалённого бизнеса — отдельное сообщение вместо «חסום».
    await expect(notice).toContainText('החשבון העסקי נמחק');
    await expect(notice).toContainText(
      'החשבון העסקי שהמשתמש שלכם שייך אליו נמחק, והגישה אליו לא תחזור. אם נראה לכם שמדובר בטעות, אפשר לפנות למנהל המערכת דרך התמיכה.',
    );
    await expect(notice).not.toContainText('הגישה לחשבון חסומה');
    await expect(notice).not.toContainText('חסום');
  });

  test('гость: reason=business → «הכניסה לחשבון חסומה» (текст кадра 721:1134, с #af074d), без «נמחק» @desktop @prod-safe #92bd0e #3a666c3dd8f5b45f7892bd0e #af074d', async ({ page }) => {
    const notice = await openNotice(page, 'business');
    // «מה רצוי» #92bd0e: заблокированный бизнес — не «נמחק». С #af074d (04.11.2026) заблокированный бизнес и
    // заблокированный пользователь получают один текст кадра Figma 721:1083 (прежний «החשבון העסקי אינו פעיל» снят).
    await expect(notice).toContainText(BLOCKED_TITLE);
    await expect(notice).toContainText(BLOCKED_BODY);
    await expect(notice).not.toContainText('נמחק');
  });
});

test.describe('Вход — сообщение по причине отказа: пользователь удалён из бизнеса / заблокирован (#922c63 · #5121408da9c3e79d47922c63)', () => {
  test('гость: reason=removed → «הגישה לעסק הוסרה… צריך הזמנה חדשה», без «חסום» @desktop @prod-safe #922c63 #5121408da9c3e79d47922c63', async ({ page }) => {
    const notice = await openNotice(page, 'removed');
    // «מה רצוי» #922c63: удалённый из бизнеса не должен видеть «המשתמש שלכם חסום».
    await expect(notice).toContainText('הגישה לעסק הוסרה');
    await expect(notice).toContainText(
      'המשתמש שלכם הוסר מהעסק, ולכן לא ניתן להיכנס. כדי לחזור לעסק צריך הזמנה חדשה ממנהל/ת החשבון בעסק. לשאלות אפשר לפנות לתמיכה.',
    );
    await expect(notice).not.toContainText('חסום');
  });

  test('гость: reason=user → «הכניסה לחשבון חסומה» (текст кадра 721:1134, с #af074d), без «הוסר» @desktop @prod-safe #922c63 #5121408da9c3e79d47922c63 #af074d', async ({ page }) => {
    const notice = await openNotice(page, 'user');
    // «מה רצוי» #922c63: заблокированный — не «הוסר». С #af074d — общий текст кадра 721:1083.
    await expect(notice).toContainText(BLOCKED_TITLE);
    await expect(notice).toContainText(BLOCKED_BODY);
    await expect(notice).not.toContainText('הוסר');
  });

  test('гость: без reason → тот же «הכניסה לחשבון חסומה» (контроль, с #af074d) @desktop @prod-safe #922c63 #5121408da9c3e79d47922c63 #af074d', async ({ page }) => {
    const notice = await openNotice(page, null);
    await expect(notice).toContainText(BLOCKED_TITLE);
    await expect(notice).toContainText(BLOCKED_BODY);
  });
});
